#!/bin/bash
# migration-guard.sh — PreToolUse hook for Edit|Write|MultiEdit.
# db/migration/: a NEW pair (NNNNNN_name.up.sql + .down.sql) may be created; a file that already exists
# is never changed — a shipped migration is immutable, a schema change is the next pair.
# db/sqlc/: generated by `sqlc generate`; never hand-edited.
set -u
INPUT="$(cat)"
f=$(printf '%s' "$INPUT" | jq -r '.tool_input.file_path // .tool_input.notebook_path // empty')
[ -n "$f" ] || exit 0
ROOT="${CLAUDE_PROJECT_DIR:-/Users/devinanderson/Desktop/red_lite_cache}"
case "$f" in
  "$ROOT"/db/sqlc/*|db/sqlc/*)
    echo "migration-guard BLOCKED: $f is generated. Edit db/query/*.sql or db/migration, then run sqlc generate." >&2; exit 2 ;;
  "$ROOT"/db/migration/*|db/migration/*)
    [ -e "$f" ] && { echo "migration-guard BLOCKED: $f already exists. A shipped migration is immutable; add the next NNNNNN_*.up.sql/.down.sql pair instead." >&2; exit 2; }
    case "$(basename "$f")" in
      [0-9][0-9][0-9][0-9][0-9][0-9]_*.up.sql|[0-9][0-9][0-9][0-9][0-9][0-9]_*.down.sql|README.md) exit 0 ;;
      *) echo "migration-guard BLOCKED: $f — migrations are NNNNNN_name.up.sql / .down.sql pairs." >&2; exit 2 ;;
    esac ;;
esac
exit 0
